package com.usatov.aura.logger.core

/**
 * An event stored by the tracker.
 *
 * @property id unique identifier generated by the SDK when the event was tracked.
 * @property name event name as passed to [EventTracker.track].
 * @property properties event properties; empty if the event had none. Iteration order is the
 * order in which the properties were passed to [EventTracker.track].
 * @property timestamp creation time in Unix epoch milliseconds, taken by the SDK at the moment
 * [EventTracker.track] was called.
 * @property createdDate creation day in `DD/MM/YYYY` format, in the device time zone at the
 * moment the event was tracked. Used for grouping by day.
 * @property seen `true` once the event has been reported with [EventTracker.markSeen].
 */
public data class TrackedEvent(
    val id: String,
    val name: String,
    val properties: Map<String, String>,
    val timestamp: Long,
    val createdDate: String,
    val seen: Boolean,
)
